let ui;
export const connectERP=value=>{ui=value;};
const money=n=>new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:0}).format(Number(n||0)/100);
const nice=s=>String(s||'').replaceAll('_',' ').replaceAll('-',' ');
let filters={from:'',to:'',area:'',recycler:'',state:'',queue:''};
const params=()=>new URLSearchParams(Object.entries(filters).filter(([,v])=>v)).toString();
function table(parent,head,rows){const {node}=ui,wrap=node('div',undefined,'table-wrap'),t=node('table'),thead=node('thead'),tr=node('tr');for(const h of head)tr.append(node('th',h));thead.append(tr);t.append(thead);const body=node('tbody');for(const values of rows){const r=node('tr');for(const v of values){const cell=node('td');if(v instanceof Node)cell.append(v);else cell.textContent=v;r.append(cell);}body.append(r);}t.append(body);wrap.append(t);parent.append(wrap);}
function stat(parent,label,value,detail,accent=''){const {node}=ui,box=node('article',undefined,'stat '+accent);box.append(node('span',label,'meta'),node('strong',value),node('small',detail));parent.append(box);return box;}
export async function dashboard(){
 const {api,node,content,button,guard,openOrder}=ui,d=await api('/analytics?'+params());content.replaceChildren();
 const top=node('div',undefined,'section-heading'),heading=node('div');heading.append(node('span','CONTROL CENTRE','eyebrow'),node('h2','Every collection. Every handover. Every rupee.'),node('p','A shared view of collectors, recyclers and Freedom Value operations.','meta'));top.append(heading);button(top,'Refresh data',dashboard);content.append(top);
 const f=node('form',undefined,'filters');for(const [key,label,type]of [['from','From','date'],['to','To','date'],['area','Collection area','text']]){const l=node('label',label),input=node('input');input.type=type;input.name=key;input.value=filters[key];input.placeholder=key==='area'?'All areas':'';l.append(input);f.append(l);}for(const [key,label,options]of [['recycler','Recycler',[['','All recyclers'],...(d.recyclers||[]).map(r=>[r.id,r.name||r.id])]],['state','Order state',[['','All states'],['accepted','Accepted'],['cancelled','Cancelled']]],['queue','Attention queue',[['','All orders'],['invoices','Invoice review'],['confirmations','Confirmation pending'],['disputes','Payment or delivery dispute'],['logistics','Logistics not scheduled']]]]){const l=node('label',label),select=node('select');select.name=key;for(const [value,text]of options){const option=node('option',text);option.value=value;select.append(option);}select.value=filters[key];l.append(select);f.append(l);}f.append(node('button','Apply filters'));f.onsubmit=e=>{e.preventDefault();filters=Object.fromEntries(new FormData(f));guard(dashboard);};const link=node('a','Export orders CSV','download');link.href='/api/ops/export?'+params();f.append(link);content.append(f);
 const stats=node('div',undefined,'stats'),sum=(list,account,status)=>list.filter(x=>x.account===account&&x.status===status).reduce((n,x)=>n+x.amount,0),count=(list,status)=>list.filter(x=>x.status===status).reduce((n,x)=>n+x.count,0);
 stat(stats,'Accepted orders',String(d.totals.active||0),`${d.totals.received||0} with an agreed receipt`,'primary-stat');stat(stats,'Material value',money(d.totals.quoted),'Current agreed quotes; prices can change');stat(stats,'Collector receipts',money(sum(d.payments,'material','confirmed')),'Confirmed by collectors');stat(stats,'Awaiting confirmation',money(sum(d.payments,'material','pending')),'External payments recorded by finance');content.append(stats);
 const panels=node('div',undefined,'dashboard-grid'),pipeline=node('section',undefined,'panel'),financial=node('section',undefined,'panel');pipeline.append(node('h3','Movement of material'),node('p','Physical custody is separate from settlement.','meta'));
 const total=Math.max(1,d.totals.total||0);for(const p of d.pipeline){const row=node('div',undefined,'pipeline-row'),track=node('progress');track.max=total;track.value=p.count;row.append(node('span',nice(p.state)),track,node('strong',String(p.count)));pipeline.append(row);}if(!d.pipeline.length)pipeline.append(node('p','Orders will appear after a recycler accepts a collector’s request.','empty'));
 financial.append(node('h3','Two separate ledgers'));table(financial,['Account','Approved invoices','Confirmed','Pending','Outstanding'],['material','logistics'].map(account=>[nice(account),money(sum(d.invoices,account,'acknowledged')),money(sum(d.payments,account,'confirmed')),money(sum(d.payments,account,'pending')),money(d.dues?.find(x=>x.account===account)?.outstanding||0)]));financial.append(node('p','Recycler pays logistics separately. Collector material proceeds are never reduced by the transport charge. Outstanding uses current approved invoices, less confirmed receipts; pending transfers are not deducted.','meta'));panels.append(pipeline,financial);content.append(panels);
 const attention=node('section',undefined,'panel');attention.append(node('h3','Needs attention'));const queue=node('div',undefined,'queue');for(const [key,label,detail]of [['invoices','Invoice reviews','Orders with a current invoice awaiting agreement'],['confirmations','Confirmations pending','Orders with external transfers awaiting receipt confirmation'],['disputes','Disputes','Orders with a payment dispute or open delivery issue'],['logistics','Logistics to arrange','Accepted orders with no pickup schedule']]){const card=stat(queue,label,String(d.attention?.[key]||0),detail);button(card,'View orders',()=>{filters.queue=key;return dashboard();});}if(filters.queue)button(attention,'Show all orders',()=>{filters.queue='';return dashboard();});attention.append(queue);content.append(attention);
 const orders=node('section',undefined,'panel');orders.append(node('h3','Collector → recycler activity'));const search=node('input');search.placeholder='Search names, area, delivery or payment state';search.setAttribute('aria-label','Search loaded orders');orders.append(search);const orderTable=node('div');orders.append(orderTable);const render=()=>{orderTable.replaceChildren();const needle=search.value.trim().toLowerCase(),list=d.orders.filter(o=>[o.collector,o.recycler,o.locality,o.delivery,o.paymentState].join(' ').toLowerCase().includes(needle));table(orderTable,['Order & parties','Area','Delivery','Material quote','Payment','Action'],list.map(o=>{const detail=node('div');detail.append(node('strong',(o.collector||'Collector')+' → '+(o.recycler||'Recycler')),node('small',o.id.slice(0,8),'muted-block'));const action=node('div',undefined,'actions');button(action,'Open',()=>openOrder(o.id));button(action,'Finance',()=>financeWorkspace(o.id));return [detail,o.locality,nice(o.state==='cancelled'?'cancelled':o.delivery)+(o.issues?' · '+o.issues+' issue(s)':''),money(o.material_paise),o.paymentState,action];}));if(!list.length)orderTable.append(node('p','No orders match this view. Once accounts create and accept requests, the records appear here.','empty'));};search.oninput=render;render();if(d.truncated)orders.append(node('p','Showing the latest 1,000 orders. Narrow the filters for a complete export.','notice'));content.append(orders);
 const bottom=node('div',undefined,'dashboard-grid'),network=node('section',undefined,'panel'),activity=node('section',undefined,'panel');network.append(node('h3','Network & material'),node('p',`${d.network.collectors} collectors · ${d.network.recyclers} recyclers · ${d.network.activeRequirements} active buying requirements`));table(network,['Unit','Requested','Agreed receipt'],d.quantities.map(q=>[q.unit,q.unit==='kg'?(q.requested/1000).toLocaleString('en-IN'):q.requested,q.unit==='kg'?(q.received/1000).toLocaleString('en-IN'):q.received]));network.append(node('p','Kilograms and pieces are reported separately.','meta'));for(const s of d.supply)network.append(node('p',`${s.lines} confirmed draft lines · ${s.unit==='kg'?s.quantity/1000:s.quantity} ${s.unit} declared stock across the network`));
 activity.append(node('h3','Latest activity'));for(const e of d.activity.slice(0,8)){const row=node('div',undefined,'activity-row');row.append(node('span',nice(e.kind)),node('small',new Date(e.created_at).toLocaleString('en-IN')));button(row,e.order_id.slice(0,8),()=>openOrder(e.order_id));activity.append(row);}if(!d.activity.length)activity.append(node('p','Activity appears here as people work through their orders.','empty'));bottom.append(network,activity);content.append(bottom);
 const trend=node('section',undefined,'panel');trend.append(node('h3','Order trend'),node('p','Most recent 30 days with accepted orders in the selected period.','meta'));table(trend,['Date','Orders','Material quote value'],d.trends.map(x=>[x.day,x.orders,money(x.quoted)]));content.append(trend);const conversion=node('section',undefined,'panel');conversion.append(node('h3','Requests & category reviews'));const requested=(d.requests||[]).reduce((sum,r)=>sum+r.count,0),accepted=(d.requests||[]).find(r=>r.state==='accepted')?.count||0;conversion.append(node('p',requested?accepted+' of '+requested+' requests accepted ('+(accepted*100/requested).toFixed(1)+'%)':'No requests in this period.'));table(conversion,['Request state','Count'],(d.requests||[]).map(r=>[nice(r.state),r.count]));conversion.append(node('p',(d.reviews?.reviews||0)+' detailed category review events across '+(d.reviews?.requests||0)+' requests. Reviews are not a measure of model accuracy.','meta'));table(conversion,['Broad category','Unit','Orders','Requested','Agreed receipt'],(d.categories||[]).map(c=>[c.code,c.unit,c.orders,c.unit==='kg'?c.requested/1000:c.requested,c.unit==='kg'?c.received/1000:c.received]));content.append(conversion,node('p',d.scope+' Updated '+new Date(d.generatedAt).toLocaleString('en-IN')+'.','meta'));
}
export async function financeWorkspace(id){
 const {api,node,content,button,form,field,mutate,staff}=ui,d=await api('/orders/'+id+'/finance'),o=d.order,base='/orders/'+id+'/finance',canRecord=['finance','operations_finance'].includes(staff().role);
 content.replaceChildren(node('span','INVOICES & EXTERNAL SETTLEMENTS','eyebrow'),node('h2','Financial record'));const actions=node('div',undefined,'actions');button(actions,'Dashboard',dashboard);button(actions,'Logistics',()=>ui.openOrder(id));button(actions,'Refresh',()=>financeWorkspace(id));content.append(actions);
 content.append(node('p','Payments happen outside the app. Finance records the transfer; the collector confirms material proceeds. Revisions and corrections remain visible.','meta'));
 const grid=node('div',undefined,'stats');for(const a of d.accounts){stat(grid,nice(a.account)+' confirmed','₹'+a.confirmed,`Approved ₹${a.approved} · Pending ₹${a.pending}`);stat(grid,nice(a.account)+' outstanding','₹'+a.outstanding,`Overpayment ₹${a.overpaid} · ${nice(a.invoiceStatus)}${a.basisChanged?' · terms changed':''}`);}content.append(grid);
 const documentLink=(parent,doc,label)=>{const a=node('a',label);a.href=base.replace('/orders','/api/ops/orders')+'/documents/'+doc;a.target='_blank';a.rel='noopener';parent.append(a);};
 for(const v of d.invoices){const card=node('article',undefined,'panel');card.append(node('h3',nice(v.account)+' · '+v.number+' · revision '+v.version),node('p',money(v.amount_paise)+' · '+nice(v.status)),node('p','Issuer: '+v.issuer+' · Issued '+v.issued_on),node('p',v.reason));documentLink(card,v.document_id,'Download invoice');for(const r of d.reviews.filter(r=>r.invoice_id===v.invoice_id&&r.version===v.version))card.append(node('p',(r.user_id===o.collectorId?'Collector':'Recycler')+': '+r.decision+' — '+r.message,'meta'));content.append(card);}
 const action=(kind,input)=>mutate(base+'/'+kind,'POST',{expectedVersion:o.version,...input},id);
 const upload=async(input,name)=>{const file=input.files?.[0];if(!file)throw new Error('Choose a document.');if(file.size>5242880)throw new Error('Choose a document up to 5 MB.');if(!input.dataset.id)input.dataset.id=crypto.randomUUID();const response=await fetch('/api/ops'+base+'/documents/'+input.dataset.id+'?name='+encodeURIComponent(file.name),{method:'PUT',credentials:'same-origin',headers:{'Content-Type':file.type||'application/pdf'},body:file,redirect:'error'});const d=await response.json();if(!response.ok)throw new Error(d.error);return d.id;};
 if(canRecord&&o.state==='accepted'){
   let invoiceFile;const f=form(content,'Upload invoice or new revision',[['account','Invoice account','select','material',[['material','Material'],['logistics','Recycler-paid logistics']]],['issuer','Issuer / issuing business'],['number','Invoice number'],['issuedOn','Invoice date','date'],['amount','Invoice total ₹'],['reason','Submission or revision reason','textarea']],async input=>{delete input.file;await action('invoice',{...input,documentId:await upload(invoiceFile)});});invoiceFile=field(f,'file','Invoice PDF, JPG or PNG','file');invoiceFile.accept='application/pdf,image/jpeg,image/png';invoiceFile.onchange=()=>delete invoiceFile.dataset.id;
   const approved=d.invoices.filter(v=>v.version===v.current_version);
   if(approved.length){let proof;const pay=form(content,'Record external payment',[['invoiceId','Current invoice','select',approved[0].invoice_id,approved.map(v=>[v.invoice_id,nice(v.account)+' · '+v.number+' · '+money(v.amount_paise)+' · '+v.status])],['amount','Amount transferred ₹'],['method','Method','select','bank_transfer',[['bank_transfer','Bank transfer'],['upi','UPI'],['cash','Cash'],['cheque','Cheque'],['other','Other']]],['reference','Transfer / receipt reference'],['paidOn','Actual payment date','date'],['evidenceReason','Explanation if proof is unavailable','textarea'],['exceptionReason','Exception explanation (overpayment, invoice or custody dispute)','textarea']],async input=>{const v=approved.find(v=>v.invoice_id===input.invoiceId);delete input.file;await action('payment',{...input,invoiceVersion:v.version,proofId:proof.files?.length?await upload(proof):null});});pay.elements.evidenceReason.required=false;pay.elements.exceptionReason.required=false;proof=field(pay,'file','Payment proof (optional)','file');proof.required=false;proof.accept='application/pdf,image/jpeg,image/png';proof.onchange=()=>delete proof.dataset.id;}
 }
 content.append(node('h2','Payment history'));if(!d.payments.length)content.append(node('p','No payments have been recorded.','empty'));
 for(const p of d.payments){const card=node('article',undefined,'panel');card.append(node('h3',money(p.amount_paise)+' · '+nice(p.account)),node('span',nice(p.status),'pill'),node('p',nice(p.method)+' · '+p.reference+' · '+p.paid_on),node('p','Payee: '+(p.account==='material'?'Collector':p.payee)),node('p',p.evidence_reason||'Documented proof attached'));if(p.proof_id)documentLink(card,p.proof_id,'Download proof');if(p.exception_reason)card.append(node('p','Exception: '+p.exception_reason,'notice'));for(const r of d.paymentReviews.filter(r=>r.payment_id===p.id))card.append(node('p',nice(r.decision)+': '+r.reason,'meta'));if(canRecord&&p.status!=='reversed')form(card,'Request correction / reversal',[['message','Reason and evidence','textarea']],v=>action('reversal-request',{paymentId:p.id,...v}));content.append(card);}
 const events=node('details');events.append(node('summary','Financial audit history'));for(const e of d.events)events.append(node('p',new Date(e.created_at).toLocaleString('en-IN')+' · '+nice(e.kind)+' · '+e.actor));content.append(events);
}
